def next_greater_elements(nums):
    n = len(nums)
    result = [-1] * n
    for i in range(n):
        for step in range(1, n):                                           # search up to n-1 steps forward, wrapping around circularly
            j = (i + step) % n
            if nums[j] > nums[i]:
                result[i] = nums[j]
                break
    return result


if __name__ == "__main__":
    print(next_greater_elements([1, 2, 1]))

