import java.util.*;

public class Main {
    int[] nextGreaterElements(int[] nums) {
        int n = nums.length;
        int[] result = new int[n];
        Arrays.fill(result, -1);
        for (int i = 0; i < n; i++) {
            for (int step = 1; step < n; step++) {                                    // search up to n-1 steps forward, wrapping around circularly
                int j = (i + step) % n;
                if (nums[j] > nums[i]) {
                    result[i] = nums[j];
                    break;
                }
            }
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] nums = {1, 2, 1};
        System.out.println(Arrays.toString(solution.nextGreaterElements(nums)));
    }
}

