import java.util.*;

public class Main {
    int[] nextGreaterElements(int[] nums) {
        int n = nums.length;
        int[] result = new int[n];
        Arrays.fill(result, -1);
        Deque<Integer> stack = new ArrayDeque<>();                                    // a monotonic DECREASING stack of indices still awaiting their answer
        for (int i = 0; i < 2 * n; i++) {                                              // conceptually walk the array TWICE, to simulate wrap-around
            int idx = i % n;
            while (!stack.isEmpty() && nums[stack.peek()] < nums[idx]) {                 // nums[idx] resolves everything smaller waiting on the stack
                result[stack.pop()] = nums[idx];
            }
            if (i < n) stack.push(idx);                                                    // only PUSH new indices during the first pass (avoids duplicates)
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] nums = {1, 2, 1};
        System.out.println(Arrays.toString(solution.nextGreaterElements(nums)));
    }
}

